/// <summary>
/// Find record
/// </summary>
/// <param name = "_guideID">_guideID</param>
/// <returns>METSalesOrderGuideTable</returns>
static METSalesOrderGuideTable find(METSalesOrderGuideID _guideID, boolean _forUpdate = false)
{
    METSalesOrderGuideTable guide;
    guide.selectForUpdate(_forUpdate);
    select firstonly guide
        where   guide.SalesOrderGuideID == _guideID;
    return guide;
}

/// <summary>
/// Find sales order guide. Throw exception if not found.
/// </summary>
/// <param name = "_guideID">_guideID</param>
/// <param name = "_forUpdate">_forUpdate</param>
/// <returns>Order guide</returns>
static METSalesOrderGuideTable findThrow(METSalesOrderGuideID _guideID, boolean _forUpdate = false)
{
    if(!_guideID)
    {
        throw error("Sales order guide has not been specified");
    }
    METSalesOrderGuideTable guide = METSalesOrderGuideTable::find(_guideID, _forUpdate);
    if(!guide)
    {
        throw error(strFmt("Sales order guide '%1' does not exist", _guideID));
    }
    return guide;
}

/// <summary>
/// Check if guide is active based on from/to date.
/// </summary>
/// <param name = "_d">Date to check against</param>
/// <returns>Result</returns>
public boolean isActiveForDate(date _d = today())
{
    if(this.FromDate && this.FromDate > _d)
    {
        return false;
    }
    if(this.ToDate && this.ToDate < _d)
    {
        return false;
    }
    return true;
}

/// <summary>
/// Return base guide number (without version suffix).
/// </summary>
/// <returns>Base guide number</returns>
public METSalesOrderGuideID baseGuideID()
{
    if(this.VersionNum == 0)
    {
        return this.SalesOrderGuideID;
    }
    else
    {
        int dashIndex = strFind(this.SalesOrderGuideID, '-', 999, -999);
        if(dashIndex)
        {
            return subStr(this.SalesOrderGuideID, 1, dashIndex - 1);
        }
        else
        {
            return this.SalesOrderGuideID;
        }
    }
}

/// <summary>
/// Get next order guide ID from number sequence.
/// </summary>
/// <returns>Order guide ID</returns>
static METSalesOrderGuideID nextOrderGuideID()
{
    return NumberSeq::newGetNum(NumberSeqReference::findReference(extendedTypeNum(METSalesOrderGuideID))).num();
}

/// <summary>
/// insert
/// </summary>
public void insert()
{
    if(!this.SalesOrderGuideID)
    {
        this.SalesOrderGuideID      = METSalesOrderGuideTable::nextOrderGuideID();  
        this.Status                 = METSalesOrderGuideStatus::New;
    }
    super();
}
